#!/usr/bin/env bash\nset -e\n\n# Force a known random seed so the output is predictable\nRANDOM=0\n\n# Run the script and capture its output\noutput=$(../src/zen_comment.sh)\n\n# Expected comment (first quote in the list)\nexpected="comment=💡 The journey of a thousand miles begins with one step."\n\nif [[ "$output" == "$expected" ]]; then\n  echo "PASS: output matches expected"\n  exit 0\nelse\n  echo "FAIL: output does not match expected"\n  echo "Got: $output"\n  echo "Expected: $expected"\n  exit 1\nfi
